def to_cents(price_str):
    """'4.50' -> 450, '4.5' -> 450, '10' -> 1000."""
    dollars, dot, cents = price_str.partition(".")
    if not dot:
        return int(dollars) * 100
    # BUG: cents not zero-padded, so "4.5" -> 405 instead of 450
    return int(dollars) * 100 + int(cents)

