def greet(name):
    return f"hello {name}"


def add(a, b):
    return str(int(a) + int(b))


COMMANDS = {"greet": greet, "add": add}


def main(argv):
    cmd = COMMANDS[argv[1]]
    # BUG: passes the command name itself as the first argument
    return cmd(*argv[1:])


if __name__ == "__main__":
    print(main(sys.argv))

