import subprocess
import sys


def run(*args):
    r = subprocess.run(
        [sys.executable, "cli.py", *args],
        capture_output=True, text=True, timeout=30,
    )
    return r.returncode, r.stdout.strip()


def test_greet():
    code, out = run("greet", "bob")
    assert code == 0 and out == "hello bob"


def test_add():
    code, out = run("add", "2", "3")
    assert code == 0 and out == "5"
